"""Named frequency memories saved under ``~/.config/pisdr/memories.json``.

A memory may carry a ``group`` (shown as a filter on the memories page and used by memory
scan) and a UTC schedule: ``utc`` is ``"HH:MM-HH:MM"`` and ``days`` an optional list such as
``"Mon,Wed"``. Memories with a schedule are "on now" only inside that window.
"""
from __future__ import annotations

import json
import logging
import time
from dataclasses import asdict, dataclass

from . import config

log = logging.getLogger(__name__)

DAY_NAMES = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")


@dataclass
class Memory:
    name: str
    vfo_hz: int
    mode: str
    step_hz: int
    group: str = ""
    utc: str = ""      # "HH:MM-HH:MM" (UTC); empty = no schedule
    days: str = ""     # "Mon,Wed" (UTC day the window starts); empty = every day

    def label(self) -> str:
        return f"{self.name}\n{_fmt_mhz(self.vfo_hz)} {self.mode}"

    @property
    def scheduled(self) -> bool:
        return parse_window(self.utc) is not None

    def on_now(self, now: float | None = None) -> bool:
        """True when there is no schedule, or the current UTC time is inside it."""
        window = parse_window(self.utc)
        if window is None:
            return True
        return in_window(window, parse_days(self.days), time.gmtime(now))

    def to_json(self) -> dict:
        data = asdict(self)
        for key in ("group", "utc", "days"):
            if not data[key]:
                del data[key]
        return data


def parse_window(text: str) -> tuple[int, int] | None:
    """``"23:00-03:30"`` -> (1380, 210) minutes after 00:00 UTC, or None."""
    try:
        start, end = text.split("-")
        return _minutes(start), _minutes(end)
    except (AttributeError, ValueError):
        return None


def _minutes(hhmm: str) -> int:
    hh, mm = hhmm.strip().split(":")
    value = int(hh) * 60 + int(mm)
    if not 0 <= value <= 24 * 60:
        raise ValueError(hhmm)
    return value % (24 * 60)


def parse_days(text: str) -> set[int]:
    """``"Mon,Wed"`` -> {0, 2}; empty or unparseable -> all days."""
    days = {DAY_NAMES.index(d.strip()[:3].title()) for d in (text or "").split(",")
            if d.strip()[:3].title() in DAY_NAMES}
    return days or set(range(7))


def in_window(window: tuple[int, int], days: set[int], tm: time.struct_time) -> bool:
    start, end = window
    now_min = tm.tm_hour * 60 + tm.tm_min
    today = tm.tm_wday
    if start <= end:
        return today in days and start <= now_min < end
    # Crosses midnight: before midnight it belongs to today, after midnight to yesterday.
    if now_min >= start:
        return today in days
    return now_min < end and (today - 1) % 7 in days


def _fmt_mhz(vfo_hz: int) -> str:
    mhz = vfo_hz / 1e6
    if mhz >= 100:
        return f"{mhz:.3f}"
    if mhz >= 10:
        return f"{mhz:.4f}"
    return f"{mhz:.5f}"


def default_name(vfo_hz: int, mode: str) -> str:
    return f"{_fmt_mhz(vfo_hz)} {mode}"


def load_memories(path=None) -> list[Memory]:
    path = path or config.MEMORIES_FILE
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        memories = []
        for item in data.get("memories", []):
            mode = item.get("mode", "NFM")
            if mode not in config.MODES:
                mode = "NFM"
            memories.append(Memory(
                name=str(item.get("name") or default_name(int(item["vfo_hz"]), mode)),
                vfo_hz=int(item["vfo_hz"]),
                mode=mode,
                step_hz=int(item.get("step_hz", 1000)),
                group=str(item.get("group") or "").strip().upper()[:12],
                utc=str(item.get("utc") or "") if parse_window(str(item.get("utc") or "")) else "",
                days=str(item.get("days") or ""),
            ))
        return memories[: config.MAX_MEMORIES]
    except (OSError, ValueError, TypeError, KeyError) as exc:
        log.debug("No memories loaded: %s", exc)
        return []


def save_memories(memories: list[Memory], path=None) -> None:
    path = path or config.MEMORIES_FILE
    try:
        config.USER_CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        payload = {"memories": [m.to_json() for m in memories[: config.MAX_MEMORIES]]}
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
    except OSError as exc:
        log.warning("Could not save memories: %s", exc)

"""multimon-ng subprocess: 22.05 kHz s16le mono on stdin, one decoded message per stdout line.

The backend owns one :class:`Multimon`. The GNU Radio feed block calls :meth:`write` from the
scheduler thread; writes are non-blocking and silently dropped if multimon-ng falls behind,
so a stuck decoder can never stall the radio audio.
"""
from __future__ import annotations

import logging
import os
import shutil
import subprocess
import threading

from .. import config
from ..qt import QObject, Signal

log = logging.getLogger(__name__)


class Multimon(QObject):
    line = Signal(str)   # emitted from the reader thread; Qt queues it to the GUI thread

    def __init__(self, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self._proc: subprocess.Popen | None = None
        self._fd: int | None = None
        self.name = "OFF"

    @staticmethod
    def available() -> bool:
        return shutil.which("multimon-ng") is not None

    @property
    def running(self) -> bool:
        return self._proc is not None

    def start(self, name: str) -> str | None:
        """Start decoding *name* (a key of config.DECODERS). Returns an error text or None."""
        self.stop()
        args = config.DECODERS.get(name)
        if not args:
            return None
        exe = shutil.which("multimon-ng")
        if not exe:
            return "multimon-ng is not installed: sudo apt install multimon-ng"
        cmd = [exe, "-t", "raw", *args, "-"]
        if shutil.which("stdbuf"):
            cmd = ["stdbuf", "-oL", *cmd]   # line-buffer its stdout so messages arrive promptly
        try:
            proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                    stderr=subprocess.DEVNULL, bufsize=0)
        except OSError as exc:
            return f"multimon-ng failed to start: {exc}"
        os.set_blocking(proc.stdin.fileno(), False)
        self._proc = proc
        self._fd = proc.stdin.fileno()
        self.name = name
        threading.Thread(target=self._read, args=(proc,), name="multimon-reader", daemon=True).start()
        log.info("multimon-ng started: %s", " ".join(cmd))
        return None

    def write(self, data: bytes) -> None:
        """Called from the GNU Radio thread with s16le samples at DECODER_RATE."""
        fd = self._fd
        if fd is None:
            return
        try:
            os.write(fd, data)
        except BlockingIOError:
            pass                       # decoder is behind; drop this chunk
        except OSError:
            self._fd = None            # multimon-ng exited

    def _read(self, proc: subprocess.Popen) -> None:
        for raw in iter(proc.stdout.readline, b""):
            text = raw.decode("utf-8", "replace").strip()
            if text and not text.startswith("Enabled demodulators"):
                self.line.emit(text)
        if self._proc is proc:
            log.warning("multimon-ng exited (code %s)", proc.poll())

    def stop(self) -> None:
        proc, self._proc, self._fd = self._proc, None, None
        self.name = "OFF"
        if proc is None:
            return
        # The radio thread may be mid-write with the old fd; close it a moment later so the
        # number cannot be reused by another file while a write is still in flight.
        threading.Timer(0.5, _reap, args=(proc,)).start()


def _reap(proc: subprocess.Popen) -> None:
    try:
        proc.stdin.close()
    except OSError:
        pass
    proc.terminate()
    try:
        proc.wait(timeout=2)
    except subprocess.TimeoutExpired:
        proc.kill()

